# DOCH!: leichter Test-Look nach den Pop-ups von dasein-design (Zaehlerzeile oben, gepunkteter Rahmen, duenne Boxen). Idempotent. 02.11.2026
import re,sys
s=open('index.html',encoding='utf-8').read()
CSS='<style id="look-css">\n/* leichter Test-Look nach den Pop-ups von dasein-design */\n.app[data-mode="game"] #gbar{display:flex;justify-content:center;align-items:center;gap:8px;height:46px;font-size:13.5px;color:#666;letter-spacing:.07em}\n.app[data-mode="game"] #gbar b{color:#e30613;font-weight:400}\n.app[data-mode="game"] #gbar .tlar{position:static;width:34px;height:34px;background:none!important;margin:0}\n.app[data-mode="game"] #gbar .tlar[hidden]{display:none!important}\n.app[data-mode="game"] .stagew{padding:0 10px}\n.app[data-mode="game"] .stage{background:#f6f6f6;outline:1px dotted #b8b8b8;outline-offset:-1px;gap:6px}\n.app[data-mode="game"] .stage>*,.app[data-mode="game"] .stage>.pict,.app[data-mode="game"] .stage>:not(.pict){padding-left:12px;padding-right:12px}\n.app[data-mode="game"] .stage .pict b{font-size:1.7rem;font-weight:400;color:#222}\n.app[data-mode="game"] .stage .pict b.gh{font-size:1.05rem;font-weight:400;letter-spacing:.02em}\n.app[data-mode="game"] .stage .pict b span,.app[data-mode="game"] .stage .pict b .aend{font-weight:700}\n.app[data-mode="game"] .stage .pict .case{font-size:.68rem;letter-spacing:.16em;background:none;padding:0;color:#e30613;font-weight:400}\n.app[data-mode="game"] .stage .pict span{font-size:.8rem}\n.app[data-mode="game"] .stage .nw{font-size:1.8rem;font-weight:400}\n.app[data-mode="game"] #panel{padding:0 10px}\n.app[data-mode="game"] #panel .card{padding:12px 0 0;background:#fff}\n.app[data-mode="game"] #panel .card.df #tx{font-size:18px;line-height:1.25;font-weight:700;text-transform:none;letter-spacing:0;color:#e30613;margin-top:2px}\n.app[data-mode="game"] #panel .opts{gap:8px;margin-top:12px;align-content:start}\n.app[data-mode="game"] #panel .opt{font-size:16px;font-weight:400;padding:11px 8px;background:#fff;box-shadow:none;outline:1px dotted #9a9a96;outline-offset:-1px}\n.app[data-mode="game"] #panel .opt.ok{background:var(--lime,#d4ff3a);outline:1px solid #7a9a00;font-weight:700}\n.app[data-mode="game"] #panel .opt.bad{background:#fbe3e1;outline:1px dotted #e30613;color:#e30613}\n.app[data-mode="game"] #panel #gt{font-size:13.5px;line-height:1.4;color:#222;margin-top:10px}\n.app[data-mode="game"] #panel .nf{font-size:12px;color:#888}\n.app[data-mode="game"] #panel .card.df .top{font-size:12px;color:#888;border-top:1px dotted #b8b8b8;padding-top:8px;letter-spacing:.03em}\n.app[data-mode="game"] #panel .card.df .top .lv{background:none;padding:0;color:#888}\n.app[data-mode="game"] #panel .btns button{background:none;font-size:12px;letter-spacing:.07em;color:#666;padding:12px 0;box-shadow:none}\n.app[data-mode="game"] #panel .btns button.on{color:#e30613;font-weight:700;background:none}\n.app[data-mode="game"] #panel>.card+.btns{}\n</style>\n'
JS='<script id="look-js">(function(){const $=id=>document.getElementById(id),w=$("stagew"),bar=document.createElement("div");bar.id="gbar";bar.innerHTML=\'<span id="gk"></span>\';\nw.insertBefore(bar,w.firstChild);bar.insertBefore($("popA"),$("gk"));bar.appendChild($("popE"));\nconst two=n=>String(n).padStart(2,"0"),base=mcRender;\nfunction upd(){try{const n=(TOPICS.find(x=>x.t===T)||{}).n||"Test";$("gk").innerHTML=(T==="test"?"Test":n.split(" ")[0])+\' <b>\'+two(MC.i+1)+\'</b> / \'+two(MC.list.length);}catch(e){}}\nmcRender=function(){base.apply(this,arguments);upd();};})();\n</script>\n'
if 'id="look-css"' not in s:
    assert s.count('</head>')==1
    s=s.replace('</head>',CSS+'</head>',1)
if 'id="look-js"' not in s:
    k='<script id="upd-js">'
    assert s.count(k)==1
    s=s.replace(k,JS+k,1)
if '--noversion' not in sys.argv:
    s=re.sub(r'(<meta name="app-version" content=")([^"]*)(")',lambda mm:mm.group(1)+'2026-11-02d'+mm.group(3),s,count=1)
open('index.html','w',encoding='utf-8').write(s)
